import { createCampaign } from '~/client';
import type { CreateCampaignResponse, CampaignCreateRequest } from '~/client';

export const useCreateCampaign = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: CampaignCreateRequest): Promise<CreateCampaignResponse> =>
      createCampaign({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: async (data) => {
      showToastSuccess('Campaign created successfully');
      await navigateTo({
        name: 'recruitment-campaigns-id',
        params: { id: data.id },
      });
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    createCampaign: mutateAsync,
    isCreateCampaignLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
