<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Create Campaign" />
    <section class="flex flex-col gap-4">
      <GoBackButton subject="campaigns" :fallback-to="backRoute" />
      <AppLoader v-if="isLoading" subject="campaign" />
      <AppError v-else-if="error" :error="error" title="Failed to load campaign settings" />
      <CampaignForm
        v-else-if="settingsData"
        :initial-values="initialValues"
        :urgency-presets="settingsData.urgency_presets"
        :throttling="settingsData.throttling"
        :channel-message-cost="settingsData.channel_message_cost"
        :validation-schema="formSchema"
        :is-saving="isCreateCampaignLoading"
        submit-label="Create Campaign"
        :on-submit="onSubmit"
      >
        <template #project>
          <FormItemWrapper label="Project" name="project_id" :is-required="true">
            <template #default="{ slots }">
              <KitFormsCombobox
                id="project_id"
                :items="projectOptions"
                placeholder="Select a project"
                input-placeholder="Search projects..."
                empty-text="No projects found"
                :null-is-all="false"
                :component-field="slots.componentField"
              />
            </template>
          </FormItemWrapper>
        </template>

        <template #aside>
          <Alert variant="info">
            <AlertTitle>Auto-populated from system settings</AlertTitle>
            <AlertDescription>Edit below to override for this campaign.</AlertDescription>
          </Alert>
        </template>
      </CampaignForm>
    </section>
  </section>
</template>

<script setup lang="ts">
import {
  getAllSystemSettings,
  getSelectorProjectList,
  type CampaignCreateRequest,
  type GetAllSystemSettingsResponse,
  type GetSelectorProjectListResponse,
} from '~/client';
import { formSchema } from '~/constants/validationSchemas/campaignCreate';
import { useCreateCampaign } from '~/mutations/recruitment/createCampaign';
import { Alert, AlertTitle, AlertDescription } from '~/components/ui/alert';
import type { CampaignFormValues } from '~/components/recruitment/CampaignForm.vue';

definePageMeta({
  roles: ['admin'],
  skipNavJourney: true,
});

useHead({
  title: 'Create Campaign',
});

const route = useRoute();
const backRoute = { name: 'recruitment-campaigns' } as const;

const prefilledProjectId = computed(() => (route.query.project_id as string) || undefined);

const {
  data: settingsData,
  error: settingsError,
  isLoading: isSettingsLoading,
} = useQuery({
  key: () => ['system-settings'],
  query: (): Promise<GetAllSystemSettingsResponse> => getAllSystemSettings({ composable: '$fetch' }),
});

const {
  data: projectsData,
  error: projectsError,
  isLoading: isProjectsLoading,
} = useQuery({
  key: () => ['selector-projects-list', 'active', 'draft', 'without-campaign'] as const,
  query: (): Promise<GetSelectorProjectListResponse> =>
    getSelectorProjectList({
      composable: '$fetch',
      query: { statuses: ['active', 'draft'], without_campaign: true },
    }),
});

const projectOptions = computed<SelectItem<string>[]>(
  () => projectsData.value?.items.map((project) => ({ name: project.name, value: project.id })) ?? []
);

const isLoading = computed(() => isSettingsLoading.value || isProjectsLoading.value);
const error = computed(() => settingsError.value ?? projectsError.value);

// The form only mounts once settings have loaded (v-else-if="settingsData"), so the
// defaults pulled from general_recruitment are ready to seed initialValues directly.
const initialValues = computed<CampaignFormValues>(() => {
  const general = settingsData.value?.general_recruitment;
  return {
    name: undefined,
    project_id: prefilledProjectId.value,
    urgency_level: general?.default_urgency_level,
    selling_points: general?.selling_points ?? '',
    latest_news: general?.latest_news ?? '',
    custom_notes: general?.custom_notes ?? '',
    end_date: null,
    target_application_count: null,
    target_assignment_count: null,
  };
});

const { createCampaign, isCreateCampaignLoading } = useCreateCampaign();

const onSubmit = async (formValues: CampaignFormValues) => {
  await createCampaign(formValues as CampaignCreateRequest);
};
</script>
